        address owner = IKARMA(TARGET).owner();
        address pair = IKARMA(TARGET).uniswapV2Pair();

        // Create test address
        address tester = address(0x333);

        // First, let's fix the initial transfer issue by checking balances
        // Give some tokens to tester from owner
        uint256 transferAmount = 1000 * 10**9;

        // Check owner balance first
        uint256 ownerBalance = IKARMA(TARGET).balanceOf(owner);
        require(ownerBalance >= transferAmount, "Owner doesn't have enough tokens");

        // Transfer from owner to tester (owner is excluded from fees)
        vm.prank(owner);
        IKARMA(TARGET).transfer(tester, transferAmount);

