            abi.encodeWithSelector(
                IKARMA.transfer.selector,
                pair,
                100 * 10**9  // 100 tokens
            )
        );

        // Verify the transfer failed (reverted)
        assertFalse(success, "Transfer to pair should have reverted due to division by zero");

        // The oracle expects the _takeLiquidity function to revert
        // We've demonstrated that by causing a sell transfer that triggers it
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

